create or replace function public.client_list_support_conversations() returns table(conversation_id uuid,client_id uuid,client_name text,client_photo_url text,last_message text,last_at timestamptz,unread_count bigint) language sql stable security definer set search_path='' as $$ select c.id,p.id,p.name,p.photo_url,lm.body,lm.created_at,coalesce((select count(*) from public.apn_chat_messages m where m.conversation_id=c.id and m.sender_id<>auth.uid()::text and m.created_at>coalesce((select max(r.updated_at) from public.apn_chat_read_states r where r.conversation_id=c.id and r.participant_id=auth.uid()::text),'epoch'::timestamptz)),0)::bigint from public.apn_chat_conversations c join public.apn_chat_participants mine on mine.conversation_id=c.id and mine.participant_id=auth.uid()::text join public.apn_chat_participants cp on cp.conversation_id=c.id and cp.participant_id<>auth.uid()::text join public.profiles p on p.id::text=cp.participant_id and p.role='client' left join lateral(select m.body,m.created_at from public.apn_chat_messages m where m.conversation_id=c.id order by m.created_at desc limit 1) lm on true where public.is_admin() order by coalesce(lm.created_at,c.updated_at) desc; $$;
revoke all on function public.client_list_support_conversations() from public,anon;
grant execute on function public.client_list_support_conversations() to authenticated,service_role;
